        pg.evaluate("[...document.querySelectorAll('#tabs button')].find(b=>b.firstChild.textContent==='Movies').click()"); pg.wait_for_timeout(300)
        rec(f"P17 [{size}] tapping another kind tab (Movies) on a series page closes it and shows Movies", not pg.evaluate("!!document.querySelector('.serp')") and pg.evaluate("[...document.querySelectorAll('#tabs button')].find(b=>b.getAttribute('aria-selected')==='true').firstChild.textContent") == "Movies")
        pg.evaluate("[...document.querySelectorAll('#tabs button')].find(b=>b.firstChild.textContent==='Series').click()"); pg.wait_for_timeout(250)
        pg.evaluate("k=>document.querySelector('#grid .card[data-key=\"'+k+'\"] a.poster').click()", ms["key"]); pg.wait_for_timeout(500)
        pg.evaluate("document.querySelector('.sp-bk').click()"); pg.wait_for_timeout(300)
        rec(f"P7 [{size}] ‹ goes back to Discover", not pg.evaluate("!!document.querySelector('.serp')") and pg.evaluate("document.querySelectorAll('#grid .card').length") > 0)
        # U (17 Nov): ▶| Up next on episodes, only when the series is on Watching or Next
        pg.evaluate("k=>document.querySelector('#grid .card[data-key=\"'+k+'\"] a.poster').click()", ms["key"]); pg.wait_for_timeout(500)
        pg.evaluate("document.querySelectorAll('.sp-row')[4].querySelector('.sp-pic .more').click()"); pg.wait_for_timeout(100)
        rec(f"S1 [{size}] series not in my lists: no Up next button", not pg.evaluate("[...document.querySelectorAll('.sp-pic .ic.open .opts button')].some(b=>b.title==='Up next')"))
        pg.evaluate("k=>{const d=JSON.parse(localStorage.getItem('proto2')); d.lists.Series=['i:'+k].concat(d.lists.Series.filter(x=>x!=='i:'+k)); localStorage.setItem('proto2', JSON.stringify(d));}", ms["key"])
        pg.reload(); pg.wait_for_timeout(900)
        pg.evaluate("[...document.querySelectorAll('button')].find(b=>b.textContent.trim().startsWith('Discover')).click()"); pg.wait_for_timeout(200)
        pg.evaluate("[...document.querySelectorAll('#tabs button')].find(b=>b.firstChild.textContent==='Series').click()"); pg.wait_for_timeout(200)
        pg.evaluate("k=>document.querySelector('#grid .card[data-key=\"'+k+'\"] a.poster').click()", ms["key"]); pg.wait_for_timeout(600)
        pg.evaluate("s=>{const b=[...document.querySelectorAll('.sp-chips button')].find(b=>b.textContent==='S'+s); b&&b.click()}", s1); pg.wait_for_timeout(200)
        pg.evaluate("document.querySelectorAll('.sp-row')[4].querySelector('.sp-pic .more').click()"); pg.wait_for_timeout(100)
