        pg.evaluate("[...document.querySelectorAll('.sp-pic .ic.open .opts button')].find(b=>b.title==='Up next').click()"); pg.wait_for_timeout(250)
        rec(f"S3 [{size}] the pill moves to E5, nothing marked watched", pg.evaluate("document.querySelectorAll('.sp-row')[4].classList.contains('next') && !!document.querySelectorAll('.sp-row')[4].querySelector('.sp-un')") and f"2/{n1} watched" in pg.evaluate("document.querySelector('.sp-top small').textContent"))
